package org.sleepwell.app;
import java.time.*;import org.json.*;import org.junit.Test;import static org.junit.Assert.*;

/** Real private SQLite and injected scheduler only. No receivers, runtime, or AlarmManager calls. */
public final class AlarmDateStorageTest {
    @Test public void datedEditPersistsOneOccurrenceAndPortableRestoreKeepsDateInactive()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){Alarm before=f.load(),draft=Alarm.read(before.json());draft.days.clear();draft.date=LocalDate.parse("2026-10-27");Alarm saved=AlarmSkips.edit(f.c,store,draft,before,true);long expected=Instant.parse("2026-10-27T06:30:00Z").toEpochMilli();assertEquals(expected,f.deadlines.get(0).longValue());assertEquals(draft.date,f.load().date);assertEquals(0,f.load().next(expected,f.zone));JSONObject backup=store.backup();Backup.validate(backup);Backup.restoreData(store,backup);Alarm restored=store.alarm(1);assertEquals(draft.date,restored.date);assertFalse(restored.enabled);assertTrue(restored.days.isEmpty());assertEquals(6,restored.hour);assertEquals(30,restored.minute);}}
    @Test public void changedDateRejectsStaleEditorAndOldOccurrenceWithoutTouchingOtherAlarms()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){Alarm original=f.load(),first=Alarm.read(original.json());first.days.clear();first.date=LocalDate.parse("2026-10-27");Alarm saved=AlarmSkips.edit(f.c,store,first,original,true);Alarm stale=Alarm.read(saved.json()),next=Alarm.read(saved.json());next.date=next.date.plusDays(1);Alarm current=AlarmSkips.edit(f.c,store,next,saved,true);long old=first.next(f.now,f.zone);assertFalse(AlarmSkips.eligible(current,old,old,0,f.zone));assertThrows(IllegalStateException.class,()->AlarmSkips.edit(f.c,store,stale,saved,true));assertEquals(next.date,f.load().date);assertEquals(2,f.schedules);}}
    @Test public void malformedConflictAndNullDateRemainInvalidUntilExplicitlyRepaired()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture()){JSONObject raw=f.load().json();raw.put("days",new JSONArray());for(Object value:new Object[]{JSONObject.NULL,20261027,"2026-02-30","2026-2-7"}){raw.put("date",value);Alarm invalid=Alarm.read(raw);assertTrue(invalid.dateInvalid);assertEquals(0,invalid.next(f.now,f.zone));assertTrue(invalid.json().has("date"));}raw.put("date","2026-10-27");Alarm valid=Alarm.read(raw);assertFalse(valid.dateInvalid);assertEquals(LocalDate.parse("2026-10-27"),valid.date);raw.put("days",new JSONArray().put(2));assertTrue(Alarm.read(raw).dateInvalid);}}
}
